# -*- coding: utf-8 -*-
"""Kịch bản review tiếng Việt (phong cách Người Kể Chuyện tự nhiên, cuốn hút), chia theo beat.
Mỗi beat: (cửa sổ thời gian nguồn "m:ss-m:ss[,m:ss-m:ss]", lời dẫn chuyện).
Tên nhân vật (Hán Việt):
  沈欣冉 Thẩm Hân Nhiễm (nữ chính)   周贺川 Chu Hạ Xuyên (vị hôn phu cũ)
  徐露露 Từ Lộ Lộ (bạn thân thật, đã mất)  徐佳佳 Từ Giai Giai (em song sinh, mạo danh Lộ Lộ)
  裴既明 Bùi Ký Minh (chồng mới)      刘美兰 Lưu Mỹ Lan (mẹ Hạ Xuyên)
"""

TITLE = "BẠN THÂN MƯỢN CHỒNG SẮP CƯỚI"

BEATS = [
    # ---------------- HOOK ----------------
    ("0:04-0:16", "Chỉ còn bảy ngày nữa là bước vào lễ đường, thế nhưng cô bạn thân nhất lại thản nhiên hỏi mượn vị hôn phu của cô suốt ba năm, chỉ vì cái cớ sang nước ngoài mà không biết tiếng Anh."),
    ("0:37-0:54", "Chua xót hơn cả là người đàn ông cô đã dành trọn mười năm thanh xuân để yêu thương, lại gật đầu đồng ý không một chút đắn đo."),
    ("23:31-23:37,24:01-24:20", "Để rồi hai năm sau, khi gã đàn ông ấy quay về với giấc mộng nối lại tình xưa, thứ chào đón hắn lại là cảnh cô đang hạnh phúc bế con nhỏ bên người chồng mới."),
    ("35:04-35:22,37:01-37:10", "Thế nhưng bi kịch thật sự vẫn chưa dừng lại ở đó. Người bạn thân từng liều mạng cứu cô thoát chết năm xưa, hóa ra đã vĩnh viễn nằm lại dưới đáy vực từ rất lâu rồi."),
    ("36:46-36:54,37:44-37:56", "Vậy thì kẻ suốt bao năm qua vẫn mang gương mặt ấy, sống bên cạnh cô, bòn rút tiền bạc rồi cướp luôn cả chồng sắp cưới của cô, rốt cuộc là ai?"),
    ("1:17-1:25", "Tất cả bi kịch ấy bắt đầu vào đúng ngày sinh nhật tuổi ba mươi của Thẩm Hân Nhiễm."),

    # ---------------- HỒI 1: SINH NHẬT ----------------
    ("0:05-0:16", "Ngay giữa bàn tiệc mừng tuổi mới, cô bạn thân Từ Lộ Lộ lại hồn nhiên đòi mượn vị hôn phu của Hân Nhiễm suốt ba năm trời, với lý do sang nước ngoài mà chẳng biết tiếng Anh nên cần người làm phiên dịch riêng."),
    ("0:15-0:33", "Hân Nhiễm chết lặng nhìn người bạn trước mặt, bởi chỉ còn đúng một tuần nữa là đến ngày trọng đại của đời cô. Ấy vậy mà Lộ Lộ vẫn cười nói tỉnh bơ, cho rằng mình chẳng mượn nhà cũng chẳng mượn xe, chỉ mượn tạm một người đàn ông thì có gì đáng ngại."),
    ("0:34-0:55", "Thế nhưng thái độ của vị hôn phu Chu Hạ Xuyên mới là nhát dao chí mạng. Hắn chẳng những không từ chối mà còn quay sang khuyên cô phải biết điều, lấy ơn cứu mạng năm xưa ra để ép cô nhường chồng sắp cưới suốt ba năm, rồi hứa hẹn ngày về vẫn sẽ cưới cô như cũ."),
    ("0:55-1:08", "Đúng lúc ấy, điện thoại báo tin nhắn từ một người bạn hỏi thăm về món quà sinh nhật năm nay. Hân Nhiễm chua chát gõ dòng chữ trả lời rằng, món quà lớn nhất ở tuổi ba mươi chính là phát hiện bạn trai ngoại tình với bạn thân để kịp thời cắt lỗ."),
    ("1:08-1:25", "Ngẩng đầu lên, cô gái ấy không hề khóc lóc mà chỉ bình thản chúc hai người họ cứ tự nhiên bên nhau. Mặc cho Lộ Lộ giả vờ hứa hẹn sẽ trả lại người nguyên vẹn, Hân Nhiễm chỉ buông nhẹ hai chữ không cần đầy dứt khoát."),
    ("1:29-1:42", "Được lời như cởi tấm lòng, đôi nam nữ chẳng buồn giữ kẽ thêm một giây nào nữa. Hạ Xuyên quay sang dịu dàng dỗ dành Lộ Lộ, khoe đã đặt sẵn nhà hàng Nhật sang trọng rồi dắt tay nhau rời đi, bỏ mặc chủ nhân bữa tiệc ngồi lại một mình."),
    ("1:42-1:49,1:56-2:06", "Cánh cửa vừa khép lại, Hân Nhiễm lập tức nhắn tin báo với mẹ rằng mình đã chia tay Chu Hạ Xuyên, đồng thời nhận lời cưới cậu học trò cưng của mẹ ngay trong hôn lễ bảy ngày tới."),
    ("2:07-2:27", "Sáng hôm sau, Hạ Xuyên mới thản nhiên gửi tin nhắn thông báo hoãn cưới vì lý do bất khả kháng. Nhìn màn hình điện thoại, nước mắt Hân Nhiễm lặng lẽ rơi vì tủi hổ cho mười năm thanh xuân, nhưng rồi cô nhanh chóng lau khô mi mắt, tự nhủ ở tuổi ba mươi làm lại từ đầu vẫn chưa muộn."),
    ("2:28-2:47", "Không chút dây dưa, cô gọi người đến thanh lý toàn bộ nội thất trong căn nhà tân hôn. Với một người phụ nữ đã quyết tâm buông bỏ, đến cả người đàn ông bội bạc kia cô còn chẳng tiếc, huống hồ là mấy món đồ vô tri."),
    ("2:49-3:04", "Chẳng bao lâu sau, Lộ Lộ đã vội vàng khoe lên mạng bức ảnh nắm tay tình tứ bên một gã đàn ông giấu mặt. Thế nhưng chỉ cần thoáng nhìn nốt ruồi quen thuộc trên ngón tay cái, Hân Nhiễm đã nhận ra ngay kẻ trong ảnh chính là Chu Hạ Xuyên."),
    ("3:05-3:33", "Trơ trẽn hơn, cô bạn thân quý hóa còn gọi điện về sai bảo Hân Nhiễm chuẩn bị sẵn cơm canh như một người hầu kẻ hạ. Đáp lại thói quen ăn sẵn ấy, Hân Nhiễm thẳng thừng dội một gáo nước lạnh, tuyên bố mình chẳng phải bảo mẫu để hầu hạ bất kỳ ai."),
    ("3:37-4:00", "Thấy người tình bị mắng, Hạ Xuyên lập tức giật lấy điện thoại trách móc cô hẹp hòi, lại đem món nợ cứu mạng năm xưa ra áp đặt. Hân Nhiễm chỉ cười nhạt mỉa mai rằng, ân tình năm đó chẳng phải chính hắn đang lấy thân mình ra để báo đáp thay cô rồi hay sao."),
    ("4:06-4:24", "Dứt khoát cúp máy, cô liên lạc ngay với mẹ để chốt lại chuyện đại sự. Chàng trai trẻ mà mẹ giới thiệu vô cùng chững chạc và chân thành, vì thế lễ đính hôn sẽ được cử hành ngay sau sáu ngày nữa."),

    # ---------------- HỒI 1B: VÒI TIỀN ----------------
    ("4:31-5:12", "Thế nhưng lòng tham và sự vô liêm sỉ của cặp đôi kia vẫn chưa chạm đáy. Trước ngày bay, Lộ Lộ ngang nhiên kéo Hạ Xuyên tới tận nhà Hân Nhiễm, mở miệng hỏi vay tám trăm nghìn tệ làm vốn kinh doanh nơi xứ người."),
    ("5:13-5:31", "Chưa dừng lại ở đó, Hạ Xuyên còn hào phóng trên tiền của người khác khi đòi lấy lại ba trăm nghìn tệ tiền sính lễ để gom cho nhân tình. Hân Nhiễm chẳng thèm đôi co, lập tức đồng ý trả lại toàn bộ sính lễ để cắt đứt mọi ràng buộc."),
    ("5:37-6:16", "Được đằng chân lân đằng đầu, Lộ Lộ thản nhiên giao phó người mẹ đau yếu của mình cho Hân Nhiễm mỗi tuần đưa đi khám bệnh và lo từng cân gạo chai dầu. Hạ Xuyên cũng hùa theo, yêu cầu cô phải đón cả ông bà nội của hắn về phụng dưỡng suốt ba năm hắn vắng nhà."),
    ("6:16-6:36", "Nghe những lời đòi hỏi phi lý ấy, Hân Nhiễm bật cười khinh bỉ. Cô nhắc cho gã vị hôn phu cũ nhớ rằng mình không mang họ Chu, đồng thời thẳng tay tiễn hai kẻ đang mơ tưởng giữa ban ngày ra khỏi cửa."),
    ("6:36-6:58", "Bọn họ chẳng hề hay biết, chỉ năm tiếng nữa là Hân Nhiễm sẽ đính hôn với người khác, còn căn phòng cưới cô từng bỏ tiền sửa sang giờ đã bị đập bỏ trơ trọi."),

    # ---------------- HỒI 2: ĐÍNH HÔN & TAI NẠN ----------------
    ("6:59-7:14", "Khoảnh khắc lễ đính hôn điểm giờ lành, Hân Nhiễm rạng rỡ khoác lên mình chiếc váy dạ hội màu hồng nhạt, kiêu hãnh sánh bước bên vị hôn phu mới là chàng kỹ sư trẻ Bùi Ký Minh."),
    ("7:16-7:30", "Cùng thời điểm ấy, mẹ của Hạ Xuyên phát hiện chuyện con trai mình hủy hôn để chạy theo bạn thân của vợ sắp cưới. Bà tức tốc cùng mẹ của Lộ Lộ bắt xe lao ra sân bay để ngăn cản đôi trẻ làm chuyện trái đạo lý."),
    ("7:30-7:38", "Thế nhưng tai họa ập đến bất ngờ, chiếc xe chở hai người mẹ già bị mất lái rồi lật nhào ngay giữa đường lớn."),
    ("7:38-8:01", "Toàn bộ tiếng va chạm kinh hoàng ấy vang lên rõ mồn một qua cuộc gọi chưa kịp tắt trên máy Hân Nhiễm. Cô bàng hoàng nén lại cơn run rẩy, lập tức gọi xe cấp cứu và báo cảnh sát trước khi bước lên sân khấu cử hành hôn lễ."),
    ("8:03-8:26", "Ngay khi Hạ Xuyên vừa yên vị trên khoang máy bay, Hân Nhiễm liền gọi tới báo tin dữ về vụ tai nạn của hai người mẹ, đồng thời thông báo mình đang làm lễ đính hôn. Thế nhưng gã đàn ông tự phụ ấy lại tưởng cô đang bày trò để níu kéo mình."),
    ("8:27-8:52", "Thậm chí Lộ Lộ còn giật lấy điện thoại, lớn tiếng mắng nhiếc Hân Nhiễm độc ác khi dám bịa chuyện nguyền rủa người lớn tuổi chỉ để giữ chân đàn ông. Trước sự mù quáng ấy, Hân Nhiễm chỉ buông một lời cảnh tỉnh cuối cùng rồi dứt khoát ngắt máy."),
    ("8:53-9:25", "Thoáng nghe tiếng nhạc lễ đường vang lên bên kia đầu dây, một dự cảm bất an chợt bóp nghẹt lấy tim Hạ Xuyên. Hắn hoảng loạn gào thét đòi xuống máy bay, nhưng phi cơ đã cất cánh."),
    ("9:27-9:56", "Ở phía bên này, Hân Nhiễm bình yên nắm lấy bàn tay ấm áp của Bùi Ký Minh. Chàng trai trẻ kém cô bốn tuổi nhưng đã là kỹ sư trụ cột của tập đoàn lớn với mức lương hàng triệu tệ mỗi năm, bất chấp mọi lời bàn tán để bảo vệ cô."),
    ("9:58-10:18", "Trong khi đó, trên bầu trời cao vợi, Lộ Lộ vẫn ra sức rót mật vào tai Hạ Xuyên rằng tất cả chỉ là màn kịch do Hân Nhiễm thuê người dựng lên. Và gã đàn ông ngạo mạn ấy cũng tự ru ngủ bản thân rằng người phụ nữ yêu hắn suốt mười năm sẽ chẳng bao giờ dám rời đi."),
    ("10:19-10:34,10:43-10:47", "Hắn đâu hề hay biết, ngay khoảnh khắc hắn đang mỉm cười nơi chín tầng mây, mẹ ruột của hắn là bà Lưu Mỹ Lan đã trút hơi thở cuối cùng trong phòng cấp cứu. Người mẹ đi cùng may mắn giữ được mạng sống nhưng lại vĩnh viễn mất đi đôi chân, giữa lúc những đứa con ruột thịt đều biệt vô âm tín."),

    # ---------------- HỒI 3: NƯỚC NGOÀI & TRỞ VỀ ----------------
    ("10:47-11:05", "Đặt chân tới trời Âu hoa lệ, Lộ Lộ hả hê tận hưởng cuộc sống xa hoa trong căn biệt thự rộng lớn, vui mừng vì từ nay đã có thể công khai chiếm hữu người đàn ông của bạn thân suốt ba năm trời."),
    ("11:05-11:32", "Đôi lần Hạ Xuyên định bấm số gọi về hỏi thăm tình hình ở quê nhà, nhưng đều bị Lộ Lộ khéo léo ngăn cản, viện cớ không muốn người cũ làm hỏng bầu không khí ngọt ngào của hai người."),
    ("11:35-12:00", "Thế nhưng chưa đầy hai năm sau, Hạ Xuyên đã mất hết kiên nhẫn và quyết định thu xếp hành lý về nước sớm hơn dự kiến. Lộ Lộ điên cuồng ngăn cản, trách hắn nuốt lời hứa ba năm năm xưa."),
    ("12:01-12:37", "Đến lúc này, Hạ Xuyên mới phũ phàng vạch rõ giới hạn. Hắn khẳng định trong lòng mình Hân Nhiễm vẫn luôn là người vợ danh chính ngôn thuận, còn Lộ Lộ từ đầu đến cuối chỉ là cái bóng không bao giờ được bước ra ánh sáng."),
    ("12:39-13:20", "Vừa đáp xuống sân bay quê nhà, hắn vội vã gọi cho Hân Nhiễm nhưng đầu dây bên kia chỉ vang lên những tiếng tút dài lạnh lẽo. Kỳ lạ hơn, khi hắn gọi về cho mẹ ruột và ông bà nội, tất cả các số máy cũng đều không thể liên lạc."),
    ("13:20-13:58", "Một nỗi sợ hãi mơ hồ bắt đầu xâm chiếm tâm trí Hạ Xuyên, khiến hắn bất giác nhớ lại cuộc gọi báo tin tai nạn hai năm về trước. Thế nhưng Lộ Lộ vẫn một mực gạt đi, thậm chí còn tìm cớ thoái thác không chịu về thăm nhà họ Chu cùng hắn."),
    ("14:01-14:40", "Dẹp nỗi bất an sang một bên, Hạ Xuyên quyết định đi tìm Hân Nhiễm trước tiên. Dù số điện thoại cũ đã báo hủy, hắn vẫn ngây thơ tin rằng cô chỉ đang giận dỗi như những lần trước, chỉ cần hắn xuống nước dỗ dành vài câu là mọi chuyện lại đâu vào đấy."),
    ("14:40-15:22", "Đi bên cạnh, Lộ Lộ không ngừng buông lời mỉa mai, bóng gió chuyện Hân Nhiễm đã sớm có người đàn ông khác. Cơn thịnh nộ của Hạ Xuyên ngay lập tức bùng lên, khiến Lộ Lộ cay đắng nhận ra rằng suốt hai năm qua, mình chưa từng thay thế được vị trí của Hân Nhiễm trong tim hắn."),
    ("16:07-17:18", "Hạ Xuyên lần mò tới công ty cũ nơi Hân Nhiễm từng làm việc, rồi chạy đến cả quán cà phê quen thuộc của hai người, nhưng mọi dấu vết và thông tin liên lạc của cô đều đã bị xóa sạch hoàn toàn."),
    ("17:18-17:56", "Thấy Lộ Lộ đi theo cứ liên tục than vãn mệt mỏi, Hạ Xuyên thẳng thừng buông một câu phũ phàng, nói rằng hạng phụ nữ chỉ biết đòi hỏi như cô ta vốn dĩ chỉ hợp làm nhân tình chứ chẳng bao giờ xứng làm vợ."),
    ("18:00-18:19", "Không bỏ cuộc, hắn cầm tấm ảnh cũ chạy tới khu trung tâm thương mại mà cô hay ghé thăm, hễ gặp ai cũng đưa ra dò hỏi tung tích, trong lòng vẫn ôm niềm tin mù quáng rằng mười năm tình nghĩa là thứ không thể xóa nhòa."),
    ("18:19-19:00", "Trớ trêu thay, người phụ nữ hắn đang điên cuồng tìm kiếm lại đang đứng cách đó không xa, trên tay dịu dàng bế một thiên thần nhỏ. Hắn bỏ đi hai năm thì tự cho là lựa chọn cuộc đời, nhưng lại bắt cô phải đứng yên một chỗ chờ đợi. Giờ đây, thế giới của Hân Nhiễm đã thuộc về Bùi Ký Minh và đứa con thơ của họ."),

    # ---------------- HỒI 4: ĐỐI MẶT ----------------
    ("19:01-19:30", "Khoảnh khắc bốn mắt chạm nhau, Hạ Xuyên không những không biết hối lỗi mà còn lớn tiếng trách Hân Nhiễm nhỏ nhen, vì một chuyện cỏn con mà nỡ cắt đứt liên lạc suốt hai năm ròng. Lộ Lộ đứng cạnh cũng lập tức hùa theo, chê trách cô thiếu lòng vị tha."),
    ("19:31-19:57", "Đáp lại màn kịch trơ trẽn ấy, Hân Nhiễm chỉ nhìn thẳng vào mắt Lộ Lộ bằng ánh nhìn sắc lạnh. Cô vạch trần bộ mặt thật của kẻ luôn miệng nhân danh tình bạn, kẻ đã lấy ơn cứu mạng ra làm vũ khí để ép bạn thân nhường chồng rồi thản nhiên sống chung suốt hai năm nơi xứ người."),
    ("20:01-20:36", "Quay sang Chu Hạ Xuyên, cô dõng dạc tuyên bố mối quan hệ giữa hai người đã vĩnh viễn khép lại ngay từ giây phút hắn chọn bước đi cùng người phụ nữ khác. Tiệc cưới năm xưa cô đã tự tay hủy bỏ, đồ đạc tự mua cô đã dọn sạch, và cô cũng chẳng mảy may bận tâm đến người nhà họ Chu nữa."),
    ("20:36-21:00", "Hạ Xuyên sững sờ không tin nổi người phụ nữ luôn dịu dàng với mình lại dám hủy hôn. Hân Nhiễm đanh thép vặn lại rằng, hắn đã dám bỏ rơi cô dâu bảy ngày trước đám cưới, thì cô cũng có quyền vứt bỏ cuộc hôn nhân ấy."),
    ("21:01-21:35", "Cô thẳng thắn đập tan ảo tưởng cuối cùng của gã bạn trai cũ. Việc cô xóa mọi dấu vết và đổi số điện thoại không phải là trò giận dỗi để chờ hắn quay về dỗ dành, mà là vì cô đã dứt khoát bước sang một trang đời mới không còn sự tồn tại của hắn."),
    ("21:35-22:05", "Nhìn đứa bé trên tay cô, Hạ Xuyên mất hết bình tĩnh, gào lên chất vấn tại sao cô có thể thay lòng đổi dạ nhanh đến thế. Hân Nhiễm chỉ thản nhiên nhắc cho hắn nhớ rằng hai năm không hề ngắn ngủi, và chính cô đã báo trước chuyện mình đính hôn ngay lúc hắn đang ngồi trên máy bay."),
    ("22:05-22:50", "Hoảng sợ trước nguy cơ mất cô vĩnh viễn, Hạ Xuyên vội vàng phủi sạch quan hệ với Lộ Lộ ngay trước mặt mọi người. Sự tráo trở ấy lập tức khiến Lộ Lộ phát điên, cô ả gào lên phơi bày chuyện hai người đã ăn chung ở chung suốt hơn bảy trăm ngày đêm nơi đất khách."),
    ("23:31-24:35", "Đúng giữa màn đấu tố ồn ào ấy, một bóng dáng cao lớn chững chạc bước tới, dịu dàng đón lấy đứa bé từ tay Hân Nhiễm vì sợ vợ mỏi tay. Nở nụ cười bình yên hiếm thấy, Hân Nhiễm tự hào giới thiệu với hai kẻ phản bội người chồng hợp pháp của mình, Bùi Ký Minh."),
    ("24:35-25:31", "Khi quay sang nói về Hạ Xuyên, cô chỉ gói gọn trong vài chữ ngắn ngủi là gã bạn trai cũ từng bỏ trốn sang châu Âu cùng bạn thân của vợ. Thấy Hạ Xuyên định mở miệng cãi lý, Bùi Ký Minh lập tức bước lên chắn trước mặt vợ, khẳng định quyền định nghĩa quá khứ thuộc về riêng cô."),
    ("25:31-26:05", "Bằng giọng điệu đĩnh đạc nhưng đầy uy lực, người chồng trẻ nhắc nhở Hạ Xuyên hãy biết giữ tự trọng. Mười năm thanh xuân đã là chuyện của dĩ vãng, còn hiện tại Hân Nhiễm đã là vợ của Bùi Ký Minh và là mẹ của con anh."),
    ("26:07-27:00", "Thấy thế cờ xoay chuyển, Lộ Lộ lại giở bài cũ, đem chuyện cứu mạng năm xưa ra để kể công và đạo đức giả. Lần này Hân Nhiễm không còn nhẫn nhịn, cô vạch trần từng khoản tiền, từng sự chăm sóc của gia đình mình mà Lộ Lộ đã tham lam hưởng thụ trước khi cướp luôn cả vị hôn phu của cô."),
    ("27:00-27:50", "Cô thẳng thừng lột trần sự ích kỷ của đôi nam nữ, những kẻ đã ném lại mọi gánh nặng gia đình để chạy theo sự tự do cá nhân, nhưng khi trở về lại đóng vai nạn nhân để trách người khác tuyệt tình. Ân nghĩa năm xưa tuyệt đối không phải tấm bình phong để che đậy sự đồi bại."),
    ("28:07-28:47", "Trước sự cứng rắn của Hân Nhiễm, Hạ Xuyên bỗng nhớ tới điều kinh khủng nhất mà hắn luôn cố trốn tránh. Hắn lắp bắp hỏi lại về cuộc điện thoại báo tin tai nạn giao thông vào đúng ngày hắn bay sang châu Âu hai năm trước."),
    ("28:55-29:31", "Với gương mặt lạnh như băng, Hân Nhiễm chậm rãi thuật lại sự thật ngày hôm đó. Khi bà Lưu Mỹ Lan gặp nạn nguy kịch giữa đường, cảnh sát không tài nào gọi được cho đứa con trai độc nhất, đành phải liên lạc cho cô qua danh bạ trong chiếc điện thoại đẫm máu của bà."),
    ("29:55-30:25", "Đau đớn thay, lý do người mẹ già ấy phải bỏ mạng trên đường ra sân bay lại chính là vì muốn ngăn đứa con trai bất hiếu làm chuyện có lỗi với Hân Nhiễm. Cho đến tận phút cuối đời, bà vẫn một lòng bảo vệ danh dự cho người con dâu hụt mà bà hết mực thương yêu."),
    ("30:25-30:50", "Thế nhưng đáp lại cuộc gọi cầu cứu khẩn thiết ấy, chính Hạ Xuyên lại buông lời mắng nhiếc cô bịa đặt và nguyền rủa mẹ ruột của hắn. Giờ đây, từng sự thật tàn nhẫn về vụ tai nạn và ca cấp cứu tuyệt vọng năm đó đều được phơi bày trần trụi trước mắt hắn."),
    ("30:49-31:01", "Đôi chân Hạ Xuyên run rẩy không đứng vững, hắn nghẹn giọng hỏi thăm tung tích của mẹ mình, để rồi chết sững khi nhận về câu trả lời rằng bà Lưu Mỹ Lan đã nằm dưới nấm mồ lạnh lẽo suốt hai năm qua."),
    ("31:01-31:30", "Cả bầu trời trước mắt Hạ Xuyên như sụp đổ hoàn toàn. Trong tâm trí hắn bỗng vang vọng lại lời dặn dò thống thiết của mẹ trước lúc lâm chung, khuyên hắn đừng bao giờ làm điều trái lương tâm với người con gái đã dành cả thanh xuân cho mình."),
    ("31:36-31:53", "Trong cơn tuyệt vọng tột cùng, hắn đưa bàn tay run rẩy về phía trước định níu lấy vạt áo người cũ, nhưng Hân Nhiễm đã dứt khoát quay lưng, bình thản bước đi bên cạnh tổ ấm nhỏ của riêng mình."),

    # ---------------- HỒI 5: CÚ LẬT ----------------
    ("31:54-32:40", "Giữa lúc Hạ Xuyên đang đau đớn tột độ vì cái chết của mẹ, Lộ Lộ bên cạnh chẳng hề mảy may thương xót mà chỉ cuống cuồng vòi tiền hắn để về quê. Nhìn rõ bản chất máu lạnh của nhân tình, Hạ Xuyên lạnh lùng tuyên bố chấm dứt tất cả rồi bỏ mặc cô ả giữa đường."),
    ("32:40-33:30", "Không một xu dính túi, Lộ Lộ đành phải mò về khu phố cũ tìm mẹ. Vừa thấy mặt cô ả, những người hàng xóm xung quanh đã nhìn bằng ánh mắt ghê tởm, mắng nhiếc đứa con bất hiếu đã bỏ mặc người mẹ cụt cả hai chân đau đớn kêu gào suốt hàng trăm đêm dài."),
    ("33:30-34:17", "Suốt hai năm nằm trên giường bệnh, mỗi lần tỉnh cơn mê là người mẹ già lại khản giọng gọi tên con gái, trong khi kẻ mà bà ngày đêm mong ngóng lại đang mải mê hưởng lạc nơi trời Tây."),
    ("34:19-34:55", "Tìm đến viện dưỡng lão, Lộ Lộ vội vàng quỳ sụp xuống bên giường bệnh, giả bộ khóc lóc nhận mẹ. Thế nhưng người hộ lý đứng cạnh chỉ buông một câu lạnh nhạt, tiết lộ rằng người duy nhất đóng viện phí và chăm sóc bà cụ suốt hai năm qua lại chính là Thẩm Hân Nhiễm."),
    ("34:55-35:21", "Đúng lúc ấy, người mẹ già trên giường bệnh mở trừng đôi mắt nhìn chằm chằm vào đứa con gái trước mặt, rồi bất ngờ thốt ra một câu nói khiến bầu không khí đông cứng lại. Bà khẳng định kẻ đang quỳ dưới đất hoàn toàn không phải Từ Lộ Lộ, mà là Từ Giai Giai."),
    ("35:21-36:30", "Bức màn bí mật động trời cuối cùng cũng bị xé toạc. Hóa ra Từ Lộ Lộ có một người em gái song sinh giống hệt mình về ngoại hình nhưng tâm địa lại một trời một vực. Người mẹ hiểu rõ hơn ai hết, Lộ Lộ hiền lành thật sự sẽ chẳng bao giờ lấy ơn cứu mạng ra để uy hiếp hay cướp đoạt hạnh phúc của bạn thân."),
    ("36:49-37:13", "Kinh hoàng hơn cả là sự thật về tung tích của người chị. Từ Lộ Lộ thật sự đã vĩnh viễn ra đi từ nhiều năm trước sau một tai nạn trượt chân rơi xuống vực sâu trong chuyến leo núi."),
    ("37:13-37:45", "Sau cái chết của chị gái, người em song sinh Từ Giai Giai đã lén đọc toàn bộ nhật ký và tin nhắn trong điện thoại của chị. Phát hiện Hân Nhiễm luôn mang nặng món nợ ân tình, ả liền lập tức đánh tráo thân phận, đội lốt người chị đã khuất để bòn rút tiền bạc và thao túng Hân Nhiễm suốt bao năm trời."),
    ("37:45-38:30", "Bị chính mẹ ruột vạch trần tội ác, Từ Giai Giai lộ nguyên hình là một kẻ điên loạn, lao vào giằng lấy chiếc túi đựng di vật của chị gái để phi tang chứng cứ. May mắn thay, người mẹ già đã kịp thời giao chiếc túi ấy cho hộ lý cất giữ và nhắn người gọi Hân Nhiễm tới nhận lại sự thật."),

    # ---------------- HỒI 6: SỰ THẬT ----------------
    ("38:43-39:13", "Khi Hân Nhiễm vội vã có mặt tại viện dưỡng lão, bà cụ nghẹn ngào nắm lấy tay cô trong nước mắt, nức nở nói lời tạ tội vì kẻ đã hủy hoại cuộc đời cô suốt những năm qua thực chất là đứa con gái út Từ Giai Giai."),
    ("39:25-39:52", "Nghe từng lời kể của người mẹ già, Hân Nhiễm bàng hoàng đến nghẹt thở. Bấy lâu nay cô từng oán trách bạn mình thay lòng đổi dạ, từng nghĩ mười năm tình bạn đã bị đồng tiền làm cho biến chất, nhưng có nằm mơ cô cũng không ngờ người bạn chân thành ấy đã sớm rời bỏ trần gian."),
    ("39:55-40:15", "Run rẩy lật mở cuốn nhật ký đã nhuốm màu thời gian, từng nét chữ thân thuộc của Lộ Lộ thật hiện lên trước mắt cô. Trên trang giấy nhỏ, cô gái ấy từng hồn nhiên ghi lại niềm vui giản dị khi được Hân Nhiễm mua cho cốc trà sữa, cùng lời hẹn ước ngày sau sẽ cùng nhau đi ngắm biển."),
    ("1:49-1:55,40:15-40:37", "Đọc đến trang viết về tai nạn đuối nước năm xưa, nước mắt Hân Nhiễm tuôn rơi như mưa. Lộ Lộ viết rằng hôm ấy bản thân cũng sợ hãi đến run người, nhưng chỉ cần cứu được bạn thân bình an vô sự là đủ, bởi tình bạn chân thành thì đâu cần tính toán chuyện trả ơn."),
    ("40:37-41:03", "Thậm chí trong những dòng nhật ký cuối cùng, Lộ Lộ còn tinh tế nhận ra Chu Hạ Xuyên là kẻ ích kỷ, sợ phiền phức và luôn lo lắng cho hạnh phúc của bạn mình. Đến tận ngày gặp nạn trên núi, trong chiếc điện thoại cũ của cô ấy vẫn còn lưu tấm ảnh chụp món quà sinh nhật định dành tặng Hân Nhiễm."),
    ("41:17-41:53", "Khép lại cuốn nhật ký đẫm nước mắt, Hân Nhiễm đã thấu tỏ mọi ân oán. Người bạn quá cố không hề phản bội cô, mà chính ả em gái Từ Giai Giai mới là kẻ đã đánh cắp danh tính để lừa gạt niềm tin và chiếm đoạt hai trăm nghìn tệ của cô. Không một chút khoan nhượng, cô quyết định đưa kẻ mạo danh ra tòa."),
    ("42:07-42:31", "Hiểu rõ nỗi đau trong lòng vợ, Bùi Ký Minh luôn âm thầm đứng sau ủng hộ mọi quyết định của cô. Anh hiểu rằng vụ kiện này không đơn thuần vì số tiền hai trăm nghìn tệ, mà là để rửa sạch vết nhơ cho người bạn đã khuất và bắt kẻ thủ ác phải trả giá dưới ánh sáng pháp luật."),

    # ---------------- HỒI 7: ĐỐI CHẤT ----------------
    ("43:07-44:10", "Vừa nhận được trát hầu tòa đòi lại khoản tiền lừa đảo, Từ Giai Giai đã lồng lộn tìm đến tận nơi để ăn vạ. Trong cơn túng quẫn, ả vẫn ngoan cố bám víu vào thân phận giả mạo, lớn tiếng kể công cứu mạng năm xưa để ép Hân Nhiễm phải rút đơn kiện."),
    ("44:10-44:32", "Không thèm đôi co nhiều lời, Hân Nhiễm bình thản giơ chiếc điện thoại đang bật sẵn chế độ ghi âm, dồn ả vào cái bẫy pháp lý không lối thoát. Nếu ả nhận mình là Từ Lộ Lộ thì phải lập tức hoàn trả khoản nợ hai trăm nghìn tệ, còn nếu thừa nhận là Từ Giai Giai thì sẽ phải ngồi tù vì tội mạo danh lừa đảo."),
    ("44:43-45:13", "Bị dồn vào đường cùng, Giai Giai lộ rõ bản chất trơ tráo đến tận cùng khi buông lời thách thức, rồi bất ngờ mất kiểm soát lao tới định hành hung Hân Nhiễm ngay giữa phố."),
    ("45:13-45:37", "Nhưng bàn tay của ả chưa kịp chạm tới thì Bùi Ký Minh đã nhanh chóng bước lên che chắn hoàn toàn cho vợ. Anh thẳng tay đẩy lùi kẻ điên loạn, đanh thép cảnh cáo nếu ả còn dám tới gần gia đình anh thêm một bước thì cảnh sát sẽ lập tức vào cuộc."),
    ("45:37-46:25", "Đúng vào lúc căng thẳng nhất, Chu Hạ Xuyên bất ngờ xuất hiện. Thấy chiếc phao cứu sinh duy nhất, Giai Giai vội vã lao tới bám lấy cánh tay hắn để cầu xin sự che chở, nhưng đáp lại ả chỉ là ánh mắt lạnh lẽo và xa lạ chưa từng có."),
    ("47:19-48:01", "Sau khi nghe phong thanh sự thật, điều duy nhất Hạ Xuyên muốn xác nhận lúc này là danh tính thật sự của người phụ nữ đã đi cùng hắn suốt hai năm qua. Khi tờ giấy chứng nhận thân phận được giơ lên với cái tên Từ Giai Giai rõ mồn một, gã đàn ông ấy hoàn toàn hóa đá."),
    ("48:01-48:20", "Trong sự bàng hoàng tột độ, Hạ Xuyên lắp bắp tự bào chữa rằng tất cả mọi lỗi lầm hắn gây ra chỉ vì tưởng nhầm Giai Giai là ân nhân cứu mạng của vị hôn thê. Thế nhưng Hân Nhiễm chỉ cười nhạt, đặt ngược lại một câu hỏi khiến hắn á khẩu."),
    ("48:20-48:48", "Cô chỉ thẳng vào sự giả dối trong thâm tâm hắn. Sai lầm của Chu Hạ Xuyên không nằm ở chỗ nhận nhầm người, mà nằm ở sự phản bội đã bén rễ từ trong máu. Một kẻ dám bỏ rơi vị hôn thê mười năm ngay trước ngày cưới thì dù người phụ nữ kia là ai, hắn vẫn là một kẻ bội bạc không hơn không kém."),
    ("48:48-49:31", "Nghe những lời phán xét đanh thép ấy, Hạ Xuyên suy sụp rơi nước mắt cầu xin một sự tha thứ muộn màng. Nhưng Hân Nhiễm lạnh lùng khước từ tất cả, bởi cảnh tan cửa nát nhà và nỗi đau mất mẹ hôm nay đều là quả báo từ chính sự lựa chọn của hắn hai năm về trước."),
    ("49:31-49:42", "Cầm chặt tờ giấy xác nhận thân phận trong tay, Hạ Xuyên đứng chết trân giữa đường như kẻ mất hồn, miệng không ngừng lẩm bẩm trong cơn uất hận vì nhận ra mình đã bị một ả đàn bà lừa dối đến trắng tay."),

    # ---------------- HỒI 8: BỜ BIỂN ----------------
    ("49:43-50:12", "Chỉ vài ngày sau cuộc đối chất ấy, Từ Giai Giai bất ngờ gửi cho Hân Nhiễm một tin nhắn đầy vẻ đắc thắng. Ả khoe rằng Chu Hạ Xuyên vừa chủ động hẹn ả ra bờ biển tâm sự lần cuối, ngạo nghễ cho rằng gã đàn ông kia dù miệng nói hận nhưng trong lòng vẫn chẳng thể dứt tình."),
    ("50:12-50:41", "Đọc dòng tin nhắn khiêu khích của kẻ mạo danh, Bùi Ký Minh lo lắng hỏi vợ có cần trình báo cảnh sát để đề phòng bất trắc hay không. Hân Nhiễm chỉ khẽ lắc đầu từ chối, bởi cô không muốn cuộc sống bình yên của gia đình mình tiếp tục bị cuốn vào vũng lầy của hai kẻ đó nữa."),
    ("50:43-51:25", "Thế nhưng khi hoàng hôn vừa buông xuống, chuông điện thoại của Hân Nhiễm lại bất ngờ đổ dồn. Đầu dây bên kia là giọng nói nghiêm trọng của cơ quan công an, thông báo vừa xảy ra một vụ án nghiêm trọng ngoài bờ biển và mời cô tới đồn phối hợp điều tra."),
    ("52:19-52:49", "Tại trụ sở cảnh sát, một tin tức chấn động được thông báo khiến tất cả lặng người. Đội cứu hộ vừa trục vớt được hai thi thể trôi dạt vào bờ, và danh tính không ai khác chính là Chu Hạ Xuyên cùng Từ Giai Giai."),
    ("53:55-54:36", "Đoạn băng ghi hình từ camera an ninh ven biển đã phơi bày toàn bộ bi kịch cuối cùng. Trong cơn điên loạn vì bị lừa dối đến mất mẹ mất vợ, Hạ Xuyên đã hẹn Giai Giai ra biển rồi bất ngờ ra tay trước, để rồi trong cuộc giằng co sinh tử, sóng dữ đã nhấn chìm cả hai xuống đáy biển sâu."),
    ("54:36-54:49", "Trớ trêu thay, bờ biển nơi Hân Nhiễm từng hứa sẽ đưa người bạn thân thật sự của mình tới ngắm nhìn, giờ đây lại trở thành nơi chôn vùi vĩnh viễn hai kẻ đã nhẫn tâm cướp đoạt cả tình yêu lẫn tình bạn của cô."),
    ("54:49-55:22", "Bước ra khỏi đồn cảnh sát, Bùi Ký Minh dịu dàng ôm lấy bờ vai người vợ đang trầm ngâm. Anh nhẹ nhàng nhắc cô rằng kết cục bi thảm ấy hoàn toàn do chính họ tự chuốc lấy, và cái chết cũng không thể xóa nhòa những tội lỗi mà họ đã gây ra."),

    # ---------------- HỒI 9: KHÉP LẠI ----------------
    ("55:25-55:56", "Sau bi kịch nơi bờ biển, luật sư riêng thông báo rằng vụ kiện đòi lại hai trăm nghìn tệ vẫn có thể tiếp tục được xử lý thông qua phần di sản của kẻ quá cố. Hân Nhiễm kiên quyết gật đầu theo đuổi vụ kiện đến cùng, bởi cô không cho phép Từ Giai Giai dùng cái chết để trốn tránh sự phán xét của công lý."),
    ("56:01-56:43", "Đêm khuya thanh vắng, cô lặng lẽ mở lại hàng trăm tin nhắn vòi tiền trong suốt những năm tháng qua. Những lời lẽ từng khiến cô cảm thấy mắc nợ và áy náy năm nào, giờ đây khi đọc lại mới thấy rõ bản chất của một màn tống tiền tinh vi và tàn nhẫn."),
    ("57:13-57:37", "Cô hiểu rằng mình bắt buộc phải thắng vụ kiện này, bởi chỉ khi bản án được tuyên rõ ràng dưới cái tên Từ Giai Giai, thì thanh danh của người bạn quá cố Từ Lộ Lộ mới hoàn toàn được trả lại sự trong sạch."),
    ("59:01-59:30,60:25-60:47", "Cuối cùng, tòa án cũng chính thức ban hành phán quyết cưỡng chế thi hành án đối với tài sản của Từ Giai Giai. Khoản tiền thu hồi được dù chẳng còn nguyên vẹn, nhưng với Hân Nhiễm, tờ phán quyết ấy đã đặt dấu chấm hết trọn vẹn cho những năm tháng sống trong lừa dối."),
    ("61:01-61:35", "Khi mọi ân oán đã ngủ yên, Hân Nhiễm bàn với chồng về việc đưa cậu con trai nhỏ đi viếng mộ người bạn năm xưa. Cô muốn con mình khi lớn lên sẽ được biết rằng, tuổi trẻ của mẹ từng có một người bạn chân thành đã hy sinh cả mạng sống để bảo vệ mẹ."),
    ("61:35-62:05", "Bùi Ký Minh siết chặt bàn tay vợ bằng tất cả sự thấu hiểu và trân trọng. Anh chưa bao giờ coi những tổn thương trong quá khứ của cô là gánh nặng, mà luôn sẵn lòng cùng cô đi qua giông bão để trả lại mọi ký ức về đúng vị trí tốt đẹp ban đầu."),
    ("62:19-62:52", "Ngày đến nghĩa trang, Hân Nhiễm nâng niu trên tay bức ảnh chụp chung của hai cô nữ sinh rạng rỡ dưới nắng trường năm ấy, khóe mắt bất giác nhòe đi vì những giọt lệ nghẹn ngào."),
    ("62:55-63:10", "Khi đứa trẻ ngây thơ chỉ tay vào di ảnh trên bia mộ hỏi mẹ người trong hình là ai, Hân Nhiễm khẽ mỉm cười dịu dàng, kể cho con nghe về dì Lộ Lộ, người bạn thân thiết nhất đã từng cứu mạng mẹ và chưa bao giờ làm mẹ phải đau lòng."),
    ("63:09-63:19", "Ký ức chợt ùa về sau vụ đuối nước năm xưa, khi Từ Lộ Lộ vừa gọt táo bên giường bệnh vừa mỉm cười trong trẻo, bảo rằng mình cứu bạn là vì tình nghĩa chứ đâu cần bạn mang nợ cả đời."),
    ("63:19-63:52", "Chẳng ai có thể ngờ được rằng nhiều năm sau đó, lòng tham của một kẻ máu mủ lại nhẫn tâm lợi dụng chính ân tình cao đẹp ấy để xoay chuyển số phận của biết bao con người. Để rồi hôm nay, hai người bạn tri kỷ năm nào phải cách nhau một tấm bia đá lạnh lẽo mới có thể tìm lại được sự thật."),
    ("64:01-64:24", "Đứng trước mộ phần của bạn, Hân Nhiễm thầm gửi lời tạ lỗi từ tận đáy lòng. Đã có những năm tháng cô từng oán trách bạn mình tham lam, từng hận bạn mình cướp đi người đàn ông cô yêu, mà không hề biết rằng linh hồn trong sáng dưới lớp đất kia cũng là một nạn nhân vô tội."),
    ("64:24-64:48", "Nỗi đau lớn nhất suốt những năm qua không phải là mất tiền bạc hay bị phản bội trong tình yêu, mà là mỗi khi nhớ về người bạn thuở thiếu thời, ký ức đẹp đẽ lại bị vấy bẩn bởi gương mặt của kẻ giả mạo, khiến ngay cả quyền được tưởng nhớ bạn thân cũng bị đánh cắp."),
    ("64:48-65:07", "Giờ đây khi mây mù đã tan biến, cô tự hứa sẽ mãi khắc ghi hình bóng rạng rỡ nhất của Từ Lộ Lộ trong tim, và sẽ kể lại câu chuyện về tình bạn đẹp đẽ ấy cho con trai mình nghe trên suốt chặng đường khôn lớn."),
    ("61:43-61:47,62:07-62:16,64:55-65:05", "Khép lại câu chuyện, có những tình bạn bị lòng tham đánh tráo và có những cuộc tình bị sự phản bội vùi chôn, nhưng chỉ cần đủ dũng khí để buông bỏ đúng lúc, người phụ nữ biết trân trọng bản thân sẽ luôn tìm thấy bến đỗ bình yên đích thực của đời mình."),
]
